/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class AlertTemplatesUnitTest {

  private static final Pattern PLACEHOLDER = Pattern.compile("\\{\\{\\{?\\s*([\\w.]+)\\s*}}}?");
  private static final List<String> FILES = List.of("alert-firing.html", "alert-firing.txt",
      "alert-firing.es.html", "alert-firing.es.txt", "alert-resolved.html", "alert-resolved.txt",
      "alert-resolved.es.html", "alert-resolved.es.txt");

  private static String read(final String name) throws IOException {
    try (InputStream in = Thread.currentThread().getContextClassLoader()
        .getResourceAsStream("migration/seed/templates/observe/" + name)) {
      Assertions.assertNotNull(in, "Missing template " + name);
      return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    }
  }

  @SuppressWarnings("unchecked")
  private static void flatten(final String prefix, final Map<String, Object> values,
      final Set<String> keys) {
    values.forEach((key, value) -> {
      String path = prefix.isEmpty() ? key : prefix + "." + key;
      if (value instanceof Map<?, ?> nested) {
        flatten(path, (Map<String, Object>) nested, keys);
      } else {
        keys.add(path);
      }
    });
  }

  @Test
  @DisplayName("Every placeholder of the seeded templates is a variable of the email channel")
  void placeholders() throws IOException {
    Set<String> keys = new HashSet<>();
    for (String status : List.of("FIRING", "RESOLVED")) {
      AlertNotification notification = new AlertNotification("a", "r", "Rule", "new-issue", status,
          "email", "ops@acme.test", "Summary", "https://observe.test/observe/#/issues/1",
          Map.of("issue", Map.of("title", "Boom")));
      flatten("", NotificationAlertChannel.variables(notification, "acme"), keys);
    }
    for (String file : FILES) {
      Matcher matcher = PLACEHOLDER.matcher(read(file));
      while (matcher.find()) {
        Assertions.assertTrue(keys.contains(matcher.group(1)),
            file + " uses {{" + matcher.group(1) + "}}, which the email channel does not fill");
      }
    }
  }
}
